        return this.canvas;
    }

    onAdd(map: Map): void {
        this.map = map;
        this.load();
        if (this.canvas) {
            if (this.animate) this.play();
        }
    }

    onRemove(): void {
        this._playing = false;
        super.onRemove();
    }

    prepare(): void {
